/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import fs from 'node:fs'
import { tokenize } from './lexer.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function main() {
  const mode = process.argv[2]
  if (mode !== 'tokens' && mode !== 'stats') {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const source = fs.readFileSync(0, 'utf8')

  let tokens
  try {
    tokens = tokenize(source)
  } catch (err) {
    if (err && err.dshLexError) {
      process.stderr.write(`error: ${err.line}:${err.col}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  if (mode === 'tokens') {
    let out = ''
    for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.text}\n`
    process.stdout.write(out)
  } else {
    const counts = { ident: 0, keyword: 0, number: 0, punct: 0, rawstring: 0, string: 0 }
    for (const t of tokens) counts[t.kind]++
    let out = ''
    for (const kind of STAT_KINDS) out += `${kind} ${counts[kind]}\n`
    out += `total ${tokens.length}\n`
    process.stdout.write(out)
  }
}

